// Swift types of the Core API contract for the iOS apps (DEC-112): the TypeScript checker resolves
// docs/02-design/service-contracts.ts (Pick, Omit, Extract, intersections, generics), and this writes, for each operation
// that service/ios/operations.json names, its input and result as Swift Codable types, with every type they reach, and the
// operations with their REST routes (shared/lib/routes.gen.ts, from the operation catalog).
//   npm run gen:swift              writes service/ios/ACKit/Sources/ACKit/Generated/*.gen.swift
//   npm run gen:swift -- --check   fails when a generated file is not current
// Mapping: an object type is a struct whose required fields are decoded strictly (a nullable one must be present, as the
// contract says "output absence is explicit null") and whose optional fields are left out when nil; a union of string
// literals is a String enum; a union of objects told apart by one literal field is an enum with one case per member; a
// literal field is a constant, checked when decoding and written when encoding; number is Double. A type the mapping
// cannot express stops the generator with its place, so a contract change never becomes a silently wrong type.
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import ts from "typescript";
import { z } from "zod";
import { coreRoutes } from "@ac/web/lib/routes.gen.ts";

const root = path.join(import.meta.dirname, "..", "..", "..");
const ios = path.join(root, "service", "ios");
const CONTRACTS = "service-contracts.ts";
const contractsPath = path.join(root, "docs", "02-design", CONTRACTS);
const outDirectory = path.join(ios, "ACKit", "Sources", "ACKit", "Generated");
const header = (what: string) =>
  `// Code generated by service/web/codegen/swift-contracts.ts from docs/02-design/service-contracts.ts${what}; DO NOT EDIT.\n` +
  "// swift-format-ignore-file\n";
const byName = (a: string, b: string) => a.localeCompare(b, "en");

const operationList = z.object({ shared: z.array(z.string()), customer: z.array(z.string()), technician: z.array(z.string()) });
const listed = operationList.parse(JSON.parse(readFileSync(path.join(ios, "operations.json"), "utf8")));
const operations = [...new Set([...listed.shared, ...listed.customer, ...listed.technician])].toSorted(byName);

const program = ts.createProgram([contractsPath], { strict: true, noEmit: true, target: ts.ScriptTarget.ES2022, lib: ["lib.es2022.d.ts"] });
const checker = program.getTypeChecker();
const source = program.getSourceFile(contractsPath);
if (!source) throw new Error(`cannot read ${contractsPath}`);

const KEYWORDS = new Set(
  ("associatedtype class deinit enum extension fileprivate func import init inout internal let open operator private " +
    "protocol public rethrows static struct subscript typealias var break case catch continue default defer do else " +
    "fallthrough for guard if in repeat return throw switch where while as any false is nil self Self super throws true " +
    "try Type some").split(" "),
);
const escaped = (name: string) => (KEYWORDS.has(name) ? `\`${name}\`` : name);
const words = (text: string) => text.split(/[^A-Za-z0-9]+/).filter((w) => w !== "");
const upper = (w: string) => w.charAt(0).toUpperCase() + w.slice(1);
// an all-capitals word (NOT_FOUND) is a word, not an acronym run: NotFound
const pascal = (text: string) => words(text).map((w) => upper(w === w.toUpperCase() ? w.toLowerCase() : w)).join("");
const camel = (text: string) => {
  const p = pascal(text);
  return p.charAt(0).toLowerCase() + p.slice(1);
};
const quoted = (text: string) => JSON.stringify(text);

/** Stops the generator: place is where the type was met (Alert.rule, jobs.get.result). */
const fail = (place: string, what: string): never => {
  throw new Error(`${place}: ${what}`);
};

// ---- the declarations written, by Swift name ----
const declarations = new Map<string, string>();
const pending = new Set<string>(); // being written: a reference while writing is fine, the struct is declared once
// TypeScript keeps one type for one set of literals: MaintenanceJob['type'] in JobSummary and in JobHistorySnapshot is
// the same union, so it is the same Swift enum (named where it is met first)
const enums = new Map<ts.Type, string>();
// the same for an object written once and met in two places: UnitAction's members are Command.action's too
const objects = new Map<ts.Type, string>();

const isNull = (t: ts.Type) => (t.flags & (ts.TypeFlags.Null | ts.TypeFlags.Undefined)) !== 0;
const isStringLiteral = (t: ts.Type): t is ts.StringLiteralType => t.isStringLiteral();
const isString = (t: ts.Type) => (t.flags & ts.TypeFlags.String) !== 0;
const isNumber = (t: ts.Type) => (t.flags & ts.TypeFlags.Number) !== 0 || t.isNumberLiteral();
const isBooleanLike = (t: ts.Type) => (t.flags & (ts.TypeFlags.Boolean | ts.TypeFlags.BooleanLiteral)) !== 0;
const isObject = (t: ts.Type) => (t.flags & ts.TypeFlags.Object) !== 0 || t.isIntersection();

// contract names that are Swift's, Foundation's or SwiftUI's own (Range, Locale, Measurement, Notification, Alert): in an
// app that imports those, the bare name would be either; the Swift type is Core… (CoreAlert, CoreLocale)
const PLATFORM_NAMES = new Set(["Alert", "Locale", "Measurement", "Notification", "Range"]);
const swiftName = (name: string) => (PLATFORM_NAMES.has(name) ? `Core${name}` : name);

/** The Swift name of the alias a type was written with (Alert → CoreAlert, Page<…>), or null for an anonymous type. */
function aliasName(t: ts.Type): string | null {
  const alias = t.aliasSymbol;
  const declaration = alias?.declarations?.[0];
  // only the contract's own aliases name a Swift type; TypeScript's (Record, Pick, Omit…) describe a shape
  return alias && declaration?.getSourceFile() === source ? swiftName(alias.name) : null;
}

/** A literal field of an object: its JSON value, written as a constant. */
function literalValue(t: ts.Type): string | null {
  if (isNull(t)) return "null";
  if (isStringLiteral(t)) return quoted(t.value);
  if (t.isNumberLiteral()) return String(t.value);
  if ((t.flags & ts.TypeFlags.BooleanLiteral) !== 0) return checker.typeToString(t);
  return null;
}

/** The members of a union without null and undefined, and whether it had either. */
function withoutNull(t: ts.Type): { members: ts.Type[]; nullable: boolean } {
  if (!t.isUnion()) return { members: [t], nullable: isNull(t) };
  const members = t.types.filter((m) => !isNull(m));
  return { members, nullable: members.length < t.types.length };
}

type Generics = ReadonlyMap<ts.Type, string>;

/** The Swift type of a TypeScript type met at place; name is the Swift name an anonymous declared type takes. */
function swiftType(t: ts.Type, place: string, name: string, generics: Generics): string {
  const generic = generics.get(t);
  if (generic) return generic;
  const { members, nullable } = withoutNull(t);
  const [first] = members;
  if (!first) return fail(place, "only null");
  const inner = members.length === 1 ? single(first, place, name, generics) : union(members, t, place, name, generics);
  return nullable ? `${inner}?` : inner;
}

function single(t: ts.Type, place: string, name: string, generics: Generics): string {
  if (isString(t)) return "String";
  if (isNumber(t)) return "Double";
  if (isBooleanLike(t)) return "Bool";
  if (isStringLiteral(t)) return stringEnum([t], aliasName(t) ?? name);
  if (checker.isArrayType(t) || checker.isTupleType(t)) {
    const element = checker.getIndexTypeOfType(t, ts.IndexKind.Number) ?? fail(place, "an array without an element type");
    return `[${swiftType(element, `${place}[]`, name, generics)}]`;
  }
  return isObject(t) ? objectType(t, place, name, generics) : fail(place, `the type ${checker.typeToString(t)}`);
}

function union(members: ts.Type[], whole: ts.Type, place: string, name: string, generics: Generics): string {
  // Mode|null is the same enum as Mode: the union without null is the one TypeScript keeps for the alias
  const plain = checker.getNonNullableType(whole);
  const own = aliasName(plain) ?? aliasName(whole) ?? name;
  if (members.every((m) => isStringLiteral(m))) {
    const known = enums.get(plain);
    if (known) return known;
    enums.set(plain, own);
    return stringEnum(members.filter((m) => isStringLiteral(m)), own);
  }
  if (members.every((m) => isBooleanLike(m))) return "Bool"; // boolean is true|false
  if (members.every((m) => isNumber(m))) return "Double";
  if (members.some((m) => isString(m)) && members.every((m) => isStringLiteral(m) || isString(m))) return "String";
  if (members.every((m) => isObject(m))) return taggedUnion(members, own, place, generics);
  return fail(place, `the union ${checker.typeToString(whole)}`);
}

function stringEnum(members: ts.StringLiteralType[], name: string): string {
  if (declarations.has(name)) return name;
  const used = new Set<string>();
  const cases = members.map((m, i) => {
    let id = camel(m.value);
    if (id === "" || /^\d/.test(id)) id = `value${id === "" ? String(i) : upper(id)}`;
    while (used.has(id)) id += String(i);
    used.add(id);
    return `  case ${escaped(id)} = ${quoted(m.value)}`;
  });
  declarations.set(name, `public enum ${name}: String, Codable, Sendable, Equatable, CaseIterable {\n${cases.join("\n")}\n}`);
  return name;
}

interface Field { json: string; swift: string; type: string; optional: boolean; constant: string | null }

/** One field of an object type: a literal field (isDemo: true, kind: 'set_power', severity: null) is a constant. */
function fieldOf(p: ts.Symbol, owner: string, generics: Generics): Field {
  const place = `${owner}.${p.name}`;
  if (!/^[A-Za-z_]\w*$/.test(p.name)) fail(place, "a field name that is no Swift identifier");
  const declaration = p.valueDeclaration ?? p.declarations?.[0];
  const type = declaration ? checker.getTypeOfSymbolAtLocation(p, declaration) : checker.getTypeOfSymbol(p);
  const optional = (p.flags & ts.SymbolFlags.Optional) !== 0;
  const base = { json: p.name, swift: escaped(p.name), optional };
  if (optional) {
    // x?: T and x?: T|null are both T? in Swift
    const plain = checker.getNonNullableType(type);
    return { ...base, type: swiftType(plain, place, `${owner}${pascal(p.name)}`, generics), constant: null };
  }
  const constant = literalValue(type);
  return constant === null
    ? { ...base, type: swiftType(type, place, `${owner}${pascal(p.name)}`, generics), constant: null }
    : { ...base, type: "", constant };
}

function objectType(t: ts.Type, place: string, name: string, generics: Generics): string {
  if (checker.getSignaturesOfType(t, ts.SignatureKind.Call).length > 0) return fail(place, "a function type");
  const strings = checker.getIndexInfosOfType(t).find((i) => isString(i.keyType));
  if (strings && checker.getPropertiesOfType(t).length === 0) {
    // Record<string, never>: the empty input of an operation that takes nothing
    if ((strings.type.flags & ts.TypeFlags.Never) === 0) return `[String: ${swiftType(strings.type, `${place}[key]`, name, generics)}]`;
    declarations.set("Empty", struct("Empty", "", []));
    return "Empty";
  }
  const alias = aliasName(t);
  const args = t.aliasTypeArguments ?? [];
  if (alias && args.length > 0) {
    genericStruct(t);
    return `${alias}<${args.map((a, i) => swiftType(a, `${place}<${String(i)}>`, `${name}Item`, generics)).join(", ")}>`;
  }
  const known = objects.get(t);
  if (known) return known;
  const own = alias ?? name;
  objects.set(t, own);
  if (!declarations.has(own) && !pending.has(own)) {
    pending.add(own);
    declarations.set(own, struct(own, "", checker.getPropertiesOfType(t).map((p) => fieldOf(p, own, generics))));
    pending.delete(own);
  }
  return own;
}

/** A generic alias (Page<T>) is declared once, with Swift generic parameters for its own. */
function genericStruct(t: ts.Type) {
  const alias = t.aliasSymbol;
  if (!alias) return;
  const name = swiftName(alias.name);
  if (declarations.has(name) || pending.has(name)) return;
  const declared = checker.getDeclaredTypeOfSymbol(alias);
  const parameters = (alias.declarations ?? []).flatMap((d) => (ts.isTypeAliasDeclaration(d) ? [...(d.typeParameters ?? [])] : []));
  const generics = new Map<ts.Type, string>(parameters.map((p) => [checker.getTypeAtLocation(p), p.name.text]));
  pending.add(name);
  const parameterList = `<${[...generics.values()].map((g) => `${g}: Codable & Sendable & Equatable`).join(", ")}>`;
  declarations.set(name, struct(name, parameterList, checker.getPropertiesOfType(declared).map((p) => fieldOf(p, name, generics))));
  pending.delete(name);
}

function decodeLine(f: Field): string {
  const key = `.${escaped(f.json)}`;
  if (f.constant === "null") return `    try Constant.expectNull(in: c, at: ${key})`;
  if (f.constant !== null) return `    try Constant.expect(${f.constant}, in: c, at: ${key})`;
  return f.optional ? `    ${f.swift} = try c.decodeIfPresent(${f.type}.self, forKey: ${key})` : `    ${f.swift} = try c.decode(${f.type}.self, forKey: ${key})`;
}

function encodeLine(f: Field): string {
  const key = `.${escaped(f.json)}`;
  if (f.constant === "null") return `    try c.encodeNil(forKey: ${key})`;
  if (f.constant !== null) return `    try c.encode(${f.constant}, forKey: ${key})`;
  return f.optional ? `    try c.encodeIfPresent(${f.swift}, forKey: ${key})` : `    try c.encode(${f.swift}, forKey: ${key})`;
}

/** A struct with its memberwise init and its Codable conformance (constants first, then the stored fields). */
function struct(name: string, parameters: string, fields: Field[]): string {
  const ordered = [...fields.filter((f) => f.constant !== null), ...fields.filter((f) => f.constant === null)];
  const stored = ordered.filter((f) => f.constant === null);
  const lines = [`public struct ${name}${parameters}: Codable, Sendable, Equatable {`];
  for (const f of stored) lines.push(`  public var ${f.swift}: ${f.type}${f.optional ? "?" : ""}`);
  const params = stored.map((f) => `${f.swift}: ${f.type}${f.optional ? "? = nil" : ""}`);
  lines.push("", `  public init(${params.join(", ")}) {`, ...stored.map((f) => `    self.${f.swift} = ${f.swift}`), "  }");
  if (ordered.length > 0) lines.push("", "  enum CodingKeys: String, CodingKey {", ...ordered.map((f) => `    case ${escaped(f.json)}`), "  }");
  lines.push("", "  public init(from decoder: any Decoder) throws {");
  if (ordered.length > 0) lines.push("    let c = try decoder.container(keyedBy: CodingKeys.self)");
  // a type without fields still writes {}: an encoder refuses a value that writes nothing
  const container = ordered.length > 0 ? "    var c = encoder.container(keyedBy: CodingKeys.self)" : "    _ = encoder.container(keyedBy: NoKeys.self)";
  lines.push(
    ...ordered.map((f) => decodeLine(f)),
    "  }",
    "",
    "  public func encode(to encoder: any Encoder) throws {",
    container,
    ...ordered.map((f) => encodeLine(f)),
    "  }",
    "}",
  );
  return lines.join("\n");
}

/** A tag value of one member: the Swift type it is decoded as, and its text ('set_power', true). */
interface TagValue { swift: "String" | "Bool"; text: string }

function tagValue(m: ts.Type, field: string): TagValue | null {
  const q = checker.getPropertyOfType(m, field);
  const type = q ? checker.getTypeOfSymbol(q) : null;
  if (type && isStringLiteral(type)) return { swift: "String", text: type.value };
  if (type && (type.flags & ts.TypeFlags.BooleanLiteral) !== 0) return { swift: "Bool", text: checker.typeToString(type) };
  return null;
}

/** The field every member has as a different literal of one kind: the tag of the union, with each member's value. */
function tagOf(members: ts.Type[]): { field: string; tagged: { member: ts.Type; value: TagValue }[] } | null {
  const [first] = members;
  const fields = first ? checker.getPropertiesOfType(first) : [];
  for (const p of fields) {
    const tagged = members
      .map((member) => ({ member, value: tagValue(member, p.name) }))
      .filter((v): v is { member: ts.Type; value: TagValue } => v.value !== null);
    const kinds = new Set(tagged.map((v) => v.value.swift));
    const texts = new Set(tagged.map((v) => v.value.text));
    if (tagged.length === members.length && kinds.size === 1 && texts.size === members.length) return { field: p.name, tagged };
  }
  return null;
}

function taggedUnion(members: ts.Type[], name: string, place: string, generics: Generics): string {
  if (declarations.has(name) || pending.has(name)) return name;
  const found = tagOf(members) ?? fail(place, `a union of objects without a tag field (${name})`);
  const tag = escaped(found.field);
  const isBool = found.tagged.some((v) => v.value.swift === "Bool");
  pending.add(name);
  const cases = found.tagged.map(({ member, value }) => ({
    id: escaped(camel(value.text)),
    literal: isBool ? value.text : quoted(value.text),
    // the member keeps its tag as a constant field, as any literal field: the same struct as where it stands alone
    memberName: objectType(member, `${place}|${value.text}`, `${name}${pascal(value.text)}`, generics),
  }));
  // true and false cover a Bool; a String tag may name a member this app does not know
  const unknown = isBool && cases.length === 2 ? [] : [`    default: throw DecodingError.dataCorruptedError(forKey: .${tag}, in: c, debugDescription: "unknown ${name}")`];
  const lines = [
    `public enum ${name}: Codable, Sendable, Equatable {`,
    ...cases.map((c) => `  case ${c.id}(${c.memberName})`),
    "",
    `  private enum Tag: String, CodingKey { case ${tag} }`,
    "",
    "  public init(from decoder: any Decoder) throws {",
    "    let c = try decoder.container(keyedBy: Tag.self)",
    `    switch try c.decode(${isBool ? "Bool" : "String"}.self, forKey: .${tag}) {`,
    ...cases.map((c) => `    case ${c.literal}: self = .${c.id}(try ${c.memberName}(from: decoder))`),
    ...unknown,
    "    }",
    "  }",
    "",
    "  public func encode(to encoder: any Encoder) throws {",
    "    switch self {",
    ...cases.map((c) => `    case .${c.id}(let value): try value.encode(to: encoder)`),
    "    }",
    "  }",
    "}",
  ];
  declarations.set(name, lines.join("\n"));
  pending.delete(name);
  return name;
}

// ---- the operations ----
const aliasNamed = (name: string) => source.statements.find((s): s is ts.TypeAliasDeclaration => ts.isTypeAliasDeclaration(s) && s.name.text === name);
const contracts = aliasNamed("OperationContracts") ?? fail(CONTRACTS, "no OperationContracts");
const contractsType = checker.getTypeAtLocation(contracts.name);

interface Operation { swift: string; name: string; input: string; result: string; write: boolean }
const written: Operation[] = operations.map((op) => {
  const entry = checker.getPropertyOfType(contractsType, op) ?? fail(op, "not in OperationContracts");
  const shape = checker.getTypeOfSymbol(entry);
  const part = (key: string) => checker.getTypeOfSymbol(checker.getPropertyOfType(shape, key) ?? fail(op, `no ${key}`));
  const swift = pascal(op);
  const mode = part("mode");
  return {
    swift,
    name: op,
    input: swiftType(part("input"), `${op}.input`, `${swift}Input`, new Map()),
    result: swiftType(part("result"), `${op}.result`, `${swift}Result`, new Map()),
    write: isStringLiteral(mode) && mode.value === "write",
  };
});
const domainError = aliasNamed("DomainError") ?? fail(CONTRACTS, "no DomainError");
swiftType(checker.getTypeAtLocation(domainError.name), "DomainError", "DomainError", new Map());

const contractsSwift = [
  header(""),
  "import Foundation",
  "",
  ...[...declarations].toSorted(([a], [b]) => byName(a, b)).map(([, d]) => `${d}\n`),
].join("\n");

// inside Ops an operation may share a contract type's name (telemetry.summary, TelemetrySummary): the types are named by module
const qualified = (type: string) => type.replaceAll(/\b[A-Z]\w*/g, (n) => (declarations.has(n) ? `ACKit.${n}` : n));
const routeLine = (r: { method: string; path: string; fixed?: readonly [string, string] }) =>
  `.init(method: .${r.method.toLowerCase()}, path: ${quoted(r.path)}${r.fixed ? `, fixed: (${quoted(r.fixed[0])}, ${quoted(r.fixed[1])})` : ""})`;
const routesOf = (op: string) => Object.entries(coreRoutes).find(([name]) => name === op)?.[1] ?? fail(op, "no REST route in the catalog");
const operationsSwift = [
  header(" and docs/02-design/operation-catalog.csv (rest_routes)"),
  "import Foundation",
  "",
  "/// The Core API operations the iOS apps call (service/ios/operations.json), by catalog name: `jobs.checkIn` is `Ops.JobsCheckIn`.",
  "public enum Ops {}",
  "",
  ...written.map((o) =>
    [
      `/// \`${o.name}\``,
      "extension Ops {",
      `public enum ${o.swift}: CoreOperation {`,
      `  public typealias Input = ${qualified(o.input)}`,
      `  public typealias Result = ${qualified(o.result)}`,
      `  public static let name = ${quoted(o.name)}`,
      `  public static let isWrite = ${String(o.write)}`,
      `  public static let routes: [CoreRoute] = [${routesOf(o.name).map((r) => routeLine(r)).join(", ")}]`,
      "}",
      "}",
      "",
    ].join("\n"),
  ),
].join("\n");

const files: [string, string][] = [["Contracts.gen.swift", contractsSwift], ["Operations.gen.swift", operationsSwift]];
const current = (file: string, text: string) => {
  try {
    return readFileSync(path.join(outDirectory, file), "utf8") === text;
  } catch {
    return false;
  }
};
if (process.argv.includes("--check")) {
  const stale = files.filter(([file, text]) => !current(file, text)).map(([file]) => file);
  if (stale.length > 0) throw new Error(`not current: ${stale.join(", ")} (run npm run gen:swift in service/web)`);
} else {
  for (const [file, text] of files) writeFileSync(path.join(outDirectory, file), text);
  process.stdout.write(`${String(written.length)} operations, ${String(declarations.size)} types → ${outDirectory}\n`);
}
